# Generated by container/bootstrap.sh - edit home/.bashrc.d/devbox.sh in the repo.
# shellcheck shell=bash

# Sourced by every shell, interactive or not: `ssh devbox <cmd>` must see the
# same toolchain a pane does.

# OMP installs here so `omp update` works without an image rebuild.
case ":$PATH:" in
*":$HOME/.local/bin:"*) ;;
*) export PATH="$HOME/.local/bin:$PATH" ;;
esac

# Node lives outside the bind-mounted home (the mount would shadow it), so nvm
# and corepack keep their state in /opt. /usr/local/bin holds node/npm/pnpm
# symlinks; nvm itself is only sourced for interactive shells, where switching
# versions is the point.
export NVM_DIR=/opt/nvm
export COREPACK_HOME=/opt/corepack

# NPM_CONFIG_PREFIX is deliberately *not* exported here: nvm refuses to activate
# its default Node when it is set ("nvm is not compatible with the
# NPM_CONFIG_PREFIX environment variable"), and the same applies to `prefix=` in
# ~/.npmrc. Global npm installs that must survive an image rebuild pass the
# prefix per call instead: `npm i -g --prefix "$HOME/.local" <pkg>`, which puts
# the binary in ~/.local/bin - already on the PATH set above.

export EDITOR=nano

# Interactive-only: prompt, aliases, and the ~100ms nvm shell function.
if [[ $- == *i* ]]; then
  [ -s "$NVM_DIR/nvm.sh" ] && . "$NVM_DIR/nvm.sh"
  eval "$(starship init bash)"
  alias lg='lazygit'
fi

# Run a command with secrets injected from 1Password, e.g. `devenv omp`.
# Selects the account by shorthand - `personal` unless OP_ACCOUNT says
# otherwise - and the matching env file, because `op run` resolves references
# against a single account per call:
#   devenv omp                         personal -> ~/.config/devbox/secrets.env
#   OP_ACCOUNT=work devenv omp      work  -> ~/.config/devbox/secrets.work.env
# Needs an active session for that account: eval "$(op signin --account <name>)".
devenv() {
  local account="${OP_ACCOUNT:-personal}"
  local env_file="$HOME/.config/devbox/secrets.env"
  [[ "${account}" == personal ]] || env_file="$HOME/.config/devbox/secrets.${account}.env"
  op run --account "${account}" --env-file="${env_file}" -- "$@"
}
